package com.yuexin.bmp.agent.task.profit.source;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
class ProfitSourceServiceTest {
 JdbcTemplate db;SourceProperties p;Fake g;ProfitSourceService s;
 static class Fake implements ProfitSourceGateway {int calls;Map<String,Object>last;Map<String,Object>intl;public Map<String,Object>domesticPage(Map<String,Object>q){calls++;last=q;Map<String,Object>row=new HashMap<>();row.put("id",1);row.put("time",1609430400000L);row.put("entCode","ENT");row.put("smsIncome","10.01");row.put("smsOperateProfit","2.01");Map<String,Object>r=new HashMap<>();r.put("data",Collections.singletonList(row));r.put("totalCount",1);return r;}public Map<String,Object>internationalDay(String d){calls++;return intl;}}
 @BeforeEach void setup(){db=new JdbcTemplate(new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa",""));db.execute("CREATE TABLE profit_source_receipt(receipt_id VARCHAR(64) PRIMARY KEY,binding_hash VARCHAR(64),payload LONGTEXT,expires_at TIMESTAMP)");db.execute("CREATE TABLE profit_international_day(data_day VARCHAR(10) PRIMARY KEY,attempts INT,state VARCHAR(20),payload LONGTEXT,raw_response LONGTEXT)");db.execute("CREATE TABLE profit_source_attempt(data_day VARCHAR(10),attempt_no INT,state VARCHAR(30),raw_response LONGTEXT,PRIMARY KEY(data_day,attempt_no))");p=new SourceProperties();g=new Fake();s=new ProfitSourceService(db,new ObjectMapper(),p,g);}
 Map<String,Object>request(){Map<String,Object>r=new HashMap<>();r.put("startDate","2021-01-01");r.put("endDate","2021-01-01");r.put("customerTypes",Arrays.asList("Customer","QuasiCustomer","Agent","CHANNEL"));r.put("taxBasis","INCLUDED");r.put("indicatorView","OPERATING");return r;}
 @Test void unconfirmedMappingFailsBeforeSource(){assertEquals("MAPPING_UNCONFIRMED",assertThrows(SourceException.class,()->s.domestic(request())).code);assertEquals(0,g.calls);}
 @Test void freezesAndBindsQueryToCriteria(){p.setMappingConfirmed(true);p.setStableReadConfirmed(true);p.setCustomerIds(Collections.singletonList(1L));p.setEnterpriseNames(Collections.singletonMap("ENT","Enterprise"));Map<String,Object>r=request();Map<String,Object>one=s.domestic(r);r.put("queryId",one.get("queryId"));assertEquals(one.get("data"),s.domestic(r).get("data"));assertEquals(1,g.calls);assertEquals(1609516800000L,g.last.get("endTime"));r.put("endDate","2021-01-02");assertEquals("SOURCE_CHANGED",assertThrows(SourceException.class,()->s.domestic(r)).code);}
 Map<String,Object>receipt(){Map<String,Object>r=new HashMap<>();r.put("source_platform","Pigeon");r.put("start_time","2021-01-01T00:00:00+08:00");r.put("end_time","2021-01-01T23:59:59+08:00");r.put("group_by",Arrays.asList("enterprise_id","account_id","send_channel_id"));r.put("truncated",false);r.put("row_count",0);r.put("rows",Collections.emptyList());return r;}
 @Test void successfulInternationalReceiptIsReusedAcrossInstances(){g.intl=receipt();Map<String,Object>r=Collections.singletonMap("dataDay","2021-01-01");s.international(r);new ProfitSourceService(db,new ObjectMapper(),p,g).international(r);assertEquals(1,g.calls);}
 @Test void badTimezoneAndSourceAreNotRetried(){g.intl=receipt();g.intl.put("start_time","2021-01-01T00:00:00Z");Map<String,Object>r=Collections.singletonMap("dataDay","2021-01-01");assertThrows(SourceException.class,()->s.international(r));assertThrows(SourceException.class,()->s.international(r));assertEquals(1,g.calls);}
 @Test void transportBudgetSurvivesNewServiceInstance(){ProfitSourceGateway bad=new ProfitSourceGateway(){public Map<String,Object>domesticPage(Map<String,Object>q){return null;}public Map<String,Object>internationalDay(String d){throw new SourceException("SOURCE_UNAVAILABLE",503,true);}};for(int i=0;i<4;i++){ProfitSourceService next=new ProfitSourceService(db,new ObjectMapper(),p,bad);assertThrows(SourceException.class,()->next.international(Collections.singletonMap("dataDay","2021-01-01")));}assertEquals(3,db.queryForObject("SELECT attempts FROM profit_international_day",Integer.class));}
 @Test void oauthEnvelopeIsUnwrappedAndRetainsTransport(){g.intl=Collections.singletonMap("body",Collections.singletonMap("content",Collections.singletonMap("content",Collections.singletonList(Collections.singletonMap("text",receipt())))));Map<String,Object> result=s.international(Collections.singletonMap("dataDay","2021-01-01"));assertEquals("YUEXIN_GATEWAY_OAUTH",((Map<?,?>)result.get("meta")).get("transport"));}
 @Test void actualGatewayReceiptWhenProvided() throws Exception {String path=System.getProperty("profit.real.receipt");org.junit.jupiter.api.Assumptions.assumeTrue(path!=null);g.intl=new ObjectMapper().readValue(new java.io.File(path),Map.class);Map<String,Object> result=s.international(Collections.singletonMap("dataDay","2026-11-26"));assertTrue(((List<?>)((Map<?,?>)result.get("receipt")).get("rows")).size()>0);}
 @Test void realJavaBridgeWhenConfigured(){org.junit.jupiter.api.Assumptions.assumeTrue("true".equals(System.getProperty("profit.real.bridge")));ProfitSourceService live=new ProfitSourceService(db,new ObjectMapper(),p,new ConfiguredSourceGateway(p,new ObjectMapper()));Map<String,Object> result=live.international(Collections.singletonMap("dataDay","2026-11-26"));Map<?,?> receipt=(Map<?,?>)result.get("receipt");assertEquals(false,receipt.get("truncated"));assertTrue(((Number)receipt.get("row_count")).intValue()>0);assertEquals(result,live.international(Collections.singletonMap("dataDay","2026-11-26")));}
}
